import java.lang.annotation.*;import java.lang.reflect.*;@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.FIELD)@interface Column{String value();}class Person{@Column("name")String name;@Column("age")int age;public String toString(){return name+" "+age;}}public class ColumnMapper{public static void main(String[]x)throws Exception{String[] h={"age","name"},d={"20","Asha"};Person p=new Person();for(Field f:Person.class.getDeclaredFields()){Column c=f.getAnnotation(Column.class);for(int i=0;i<h.length;i++)if(c.value().equals(h[i])){f.setAccessible(true);if(f.getType()==int.class)f.setInt(p,Integer.parseInt(d[i]));else f.set(p,d[i]);}}System.out.println(p);}}
